import java.util.*;

public class GraphBasics {

    // ====== 邻接表建图 ======
    static List<List<Integer>> buildUndirectedGraph(int n, int[][] edges) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) graph.add(new ArrayList<>());
        for (int[] e : edges) {
            graph.get(e[0]).add(e[1]);
            graph.get(e[1]).add(e[0]); // 无向图加双向边
        }
        return graph;
    }

    // ====== BFS 遍历 + 层数计算 ======
    static List<Integer> bfs(List<List<Integer>> graph, int start) {
        List<Integer> order = new ArrayList<>();
        boolean[] visited = new boolean[graph.size()];
        Queue<Integer> queue = new LinkedList<>();
        queue.offer(start);
        visited[start] = true; // 入队时标记，不是出队时
        while (!queue.isEmpty()) {
            int node = queue.poll();
            order.add(node);
            for (int nei : graph.get(node)) {
                if (!visited[nei]) {
                    visited[nei] = true;
                    queue.offer(nei);
                }
            }
        }
        return order;
    }

    // ====== DFS 遍历（递归版） ======
    static List<Integer> dfs(List<List<Integer>> graph, int start) {
        List<Integer> order = new ArrayList<>();
        boolean[] visited = new boolean[graph.size()];
        dfsHelper(graph, start, visited, order);
        return order;
    }

    static void dfsHelper(List<List<Integer>> graph, int node,
                          boolean[] visited, List<Integer> order) {
        visited[node] = true;
        order.add(node);
        for (int nei : graph.get(node)) {
            if (!visited[nei]) {
                dfsHelper(graph, nei, visited, order);
            }
        }
    }

    // ====== 拓扑排序（Kahn / BFS 版） ======
    static List<Integer> topologicalSort(List<List<Integer>> graph, int n) {
        int[] inDegree = new int[n];
        for (int i = 0; i < n; i++)
            for (int nei : graph.get(i))
                inDegree[nei]++;

        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < n; i++)
            if (inDegree[i] == 0) queue.offer(i);

        List<Integer> result = new ArrayList<>();
        while (!queue.isEmpty()) {
            int node = queue.poll();
            result.add(node);
            for (int nei : graph.get(node)) {
                if (--inDegree[nei] == 0) queue.offer(nei);
            }
        }
        // result.size() < n 说明有环，返回空列表
        return result.size() == n ? result : new ArrayList<>();
    }

    // ====== 有向图环检测（BFS/Kahn 版） ======
    static boolean hasCycleDirected(List<List<Integer>> graph, int n) {
        int[] inDegree = new int[n];
        for (int i = 0; i < n; i++)
            for (int nei : graph.get(i))
                inDegree[nei]++;
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < n; i++)
            if (inDegree[i] == 0) queue.offer(i);
        int count = 0;
        while (!queue.isEmpty()) {
            int node = queue.poll();
            count++;
            for (int nei : graph.get(node))
                if (--inDegree[nei] == 0) queue.offer(nei);
        }
        return count != n; // 没清零的节点在环上
    }

    // ====== 无向图环检测（DFS + parent） ======
    static boolean hasCycleUndirected(List<List<Integer>> graph, int n) {
        boolean[] visited = new boolean[n];
        for (int i = 0; i < n; i++) {
            if (!visited[i] && dfsCycleCheck(graph, i, -1, visited))
                return true;
        }
        return false;
    }

    static boolean dfsCycleCheck(List<List<Integer>> graph, int node,
                                 int parent, boolean[] visited) {
        visited[node] = true;
        for (int nei : graph.get(node)) {
            if (!visited[nei]) {
                if (dfsCycleCheck(graph, nei, node, visited)) return true;
            } else if (nei != parent) {
                return true; // 遇到已访问的非父节点 → 有环
            }
        }
        return false;
    }
}
